import React from "react";

function Syntex() {
  const age = 18;

  let message;

  if (age >= 18) {
    message = <h2>You are eligible to vote ✅</h2>;
  } else {
    message = <h2>You are not eligible to vote </h2>;
  }

  return <div>{message}</div>;
}

export default Syntex;
